"""Build the pinned ISC libmypaint kernel; emscripten3.1.6, no Qt/GLib/JSON-C."""
from pathlib import Path
import tempfile,subprocess,shutil,json,hashlib,re
root=Path(__file__).resolve().parents[2];source=root/'third_party/libmypaint';lock=json.loads((source/'source-lock.json').read_text());sha=lambda b:hashlib.sha256(b).hexdigest()
with tempfile.TemporaryDirectory(prefix='grafetto-mypaint-')as temp:
    work=Path(temp)
    for row in lock['files']:
        data=(source/row['path']).read_bytes()
        if sha(data)!=row['sha256']:raise ValueError('Pinned source changed: '+row['path'])
        target=work/row['path'];target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
    s=(work/'mypaint-brush.c').read_text();s=s[:s.index('// Compat wrapper, for supporting libjson')]+s[s.index('void\nmypaint_brush_from_defaults'):]
    for text in ['#include <json.h>','#include "glib/mypaint-brush.c"','    json_object *brush_json;','    self->brush_json = json_object_new_object();','    if (self->brush_json) {\n        json_object_put(self->brush_json);\n    }']:s=s.replace(text,'')
    s+='\nvoid grafetto_seed(MyPaintBrush *self,unsigned seed){rng_double_set_seed(self->rng,seed & 0x3fffffff);}\n';(work/'kernel.c').write_text(s)
    (work/'config.h').write_text('#define MYPAINT_CONFIG_USE_GLIB 0\n#define MYPAINT_CONFIG_USE_INTROSPECTION 0\n#define MYPAINT_CONFIG_USE_OPENMP 0\n')
    shutil.copyfile(root/'scripts/mypaint/bridge.c',work/'bridge.c')
    subprocess.run(['python3','generate.py','mypaint-brush-settings-gen.h','brushsettings-gen.h'],cwd=work,check=True)
    exports=['create','destroy','base','mapping','point','stroke','begin','end','alloc','free']
    c=['kernel.c','bridge.c','mypaint-mapping.c','mypaint-surface.c','mypaint-brush-settings.c','rng-double.c','helpers.c','mypaint-tiled-surface.c','operationqueue.c','tilemap.c','fifo.c','brushmodes.c','mypaint-matrix.c','mypaint-symmetry.c','mypaint-rectangle.c']
    args=['emcc',*c,'-O3','-I.','--no-entry','-sSTANDALONE_WASM=1','-sFILESYSTEM=0','-sMALLOC=emmalloc','-sALLOW_MEMORY_GROWTH=1','-sINITIAL_MEMORY=2097152','-sMAXIMUM_MEMORY=67108864','-sTOTAL_STACK=65536','-sERROR_ON_UNDEFINED_SYMBOLS=0',*['-Wl,--export=grafetto_'+e for e in exports],'-o','kernel.wasm']
    subprocess.run(args,cwd=work,check=True)
    binary=(work/'kernel.wasm').read_bytes();public=root/'apps/web/public/brush-kernels';public.mkdir(exist_ok=True);(public/'mypaint-1.6.1.wasm').write_bytes(binary);(public/'mypaint-LICENSE.txt').write_text((source/'COPYING').read_text()+'\nfastapprox (included in the compiled kernel):\n'+(source/'fastapprox/fastpow.h').read_text().split('*/',1)[0]+'*/\n')
    header=(work/'mypaint-brush-settings-gen.h').read_text();settings=re.findall(r'^    MYPAINT_BRUSH_SETTING_([A-Z0-9_]+),',header,re.M);inputs=re.findall(r'^    MYPAINT_BRUSH_INPUT_([A-Z0-9_]+),',header,re.M);meta=json.loads((work/'brushsettings.json').read_text());lookup={x['internal_name']:x for x in meta['settings']}
    schema={'settings':[{'name':name.lower(),'id':i,'min':lookup[name.lower()]['minimum'],'max':lookup[name.lower()]['maximum'],'default':lookup[name.lower()]['default'],'constant':lookup[name.lower()]['constant']}for i,name in enumerate(settings)],'inputs':[x.lower()for x in inputs]}
    (root/'scripts/brush-import/mypaint_schema.json').write_text(json.dumps(schema,indent=2)+'\n')
    (root/'packages/shared/src/mypaintSchema.ts').write_text('// Generated from pinned libmypaint1.6.1 by scripts/mypaint/build.py.\nexport const MYPAINT_SCHEMA='+json.dumps(schema,separators=(',',':'))+' as const\n')
    (root/'apps/web/src/engine/src/presets/mypaintKernelBuild.ts').write_text('// Generated by scripts/mypaint/build.py.\nexport const MYPAINT_WASM_SHA256='+repr(sha(binary))+'\n')
    print(json.dumps({'bytes':len(binary),'sha256':sha(binary),'commit':lock['commit'],'settings':len(settings),'inputs':len(inputs)}))
